            "lem-nufft-gaussian-periodization-fourier-series"
          ],
          "strategy": "Use Gaussian decay and an explicit geometric majorant on each compact interval.",
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          },
          "sources": {
            "references": [
