            ]
          }
        },
        {
          "id": "lem-na-normalized-rayleigh-energy-perturbation",
          "kind": "lemma",
          "title": "Rayleigh energy perturbation for normalized finite states",
          "statement": "Let $\\mathcal H=\\mathbb F^{n_1\\times\\cdots\\times n_d}$ be a finite tensor-array space over $\\mathbb F\\in\\{\\mathbb R,\\mathbb C\\}$, let $H:\\mathcal H\\to\\mathcal H$ be self-adjoint, and let $\\psi,\\phi\\in\\mathcal H$ satisfy $\\|\\psi\\|_F=\\|\\phi\\|_F=1$. Then\n$$\\left|\\langle\\psi,H\\psi\\rangle_F-\\langle\\phi,H\\phi\\rangle_F\\right|\\le 2\\|H\\|_{\\mathrm{op}}\\|\\psi-\\phi\\|_F.$$",
