{
      "id": "numerical-algebraic-riccati-equations-and-stabilizing-branches-examples",
      "kind": "B",
      "category": "numerical-linear-algebra-and-approximation",
      "label": "LIN-RIC-B",
      "title": "Numerical algebraic riccati equations and stabilizing branches — Examples",
