    "sources": {
      "references": [
        {
          "title": "DLMF, Chapter 3, Numerical Methods, §3.1",
          "url": "https://dlmf.nist.gov/3.1"
        },
        {
          "title": "N. M. Temme, “Numerical aspects of special functions,” Acta Numerica 17 (2008), §§2–5",
