    "id": "def-pe04-upwind-dg-transport-discretization",
    "kind": "definition",
    "title": "Upwind discontinuous Galerkin discretization of constant transport",
    "deps": [
      "def-pe04-one-dimensional-interval-mesh-and-broken-polynomials",
