  {
    "id": "def-fv-regular-simplicial-companion-family",
    "strategy": "Complete same-frontier prerequisite authored by the assigned Codex escalation owner; see the exact scope report and source-local proof.",
    "kind": "definition",
    "title": "Finite-volume families with a regular simplicial companion",
    "deps": [
