  {
    "id": "thm-pe26-primal-constraints-remove-floating-kernels",
    "kind": "theorem",
    "title": "Primal constraints remove local floating kernels",
    "deps": [
      "def-pe26-primal-interface-spaces-and-jumps",
      "thm-pe26-local-energy-kernel-and-interior-spd",
