  {
    "id": "thm-pe26-harmonic-extension-minimizes-energy",
    "kind": "theorem",
    "title": "Discrete harmonic extension minimizes energy",
    "deps": [
      "def-pe26-discrete-harmonic-extension-and-schur-complement",
      "thm-pe26-local-energy-kernel-and-interior-spd"
    ],
    "justified_by": [],
    "dependency_level": 3,
    "statement": "For every admissible local trace $g_i$, $H_i g_i$ from [[def-pe26-discrete-harmonic-extension-and-schur-complement]] is the unique finite-element function with trace $g_i$ minimizing $a_i(v,v)$. The minimum is $g_i^TS_i g_i$.",
