    "id": "lem-afem-vertex-patch-poincare",
    "kind": "lemma",
    "title": "Uniform Poincare inequalities on vertex and cell patches",
    "deps": [
      "def-matching-affine-simplicial-meshes",
      "thm-reference-simplex-poincare-wirtinger",
