  {
    "id": "alg-dorfler-marking-and-conforming-nvb-refinement",
    "kind": "algorithm",
    "title": "Dorfler marking and conforming newest-vertex refinement",
    "deps": [
      "def-afem-p1-residual-estimator-and-data-oscillation",
