{
      "id": "particle-in-cell-and-particle-mesh-kinetic-methods",
      "kind": "A",
      "category": "numerical-pdes-and-spatial-discretization",
      "label": "XD-07",
      "title": "Particle in cell and particle mesh kinetic methods",
      "companion": "particle-in-cell-and-particle-mesh-kinetic-methods-examples",
      "requires": [
        "interacting-particle-mean-field-and-vortex-blob-error",
