    "id": "thm-periodic-c1-velocity-has-global-characteristic-flow",
    "kind": "theorem",
    "title": "A periodic C1 velocity has a global characteristic flow on a finite horizon",
    "deps": [
      "def-linear-transport-equation-and-its-characteristic-flow",
